{
  "action": "write_file",
  "path": "limiter.py",
  "content": "import time
import threading
from fastapi import HTTPException

class SlidingWindowRateLimiter:
    def __init__(self):
        self.lock = threading.Lock()
        self.requests = {}

    def allow_request(self, client_id, limit, window_sec):
        with self.lock:
            if client_id not in self.requests:
                self.requests[client_id] = []

            current_time = time.time()
            self.requests[client_id] = [req for req in self.requests[client_id] if current_time - req < window_sec]

            if len(self.requests[client_id]) < limit:
                self.requests[client_id].append(current_time)
                return True
            else:
                return False

    def remove_client(self, client_id):
        with self.lock:
            if client_id in self.requests:
                del self.requests[client_id]
            else:
                raise HTTPException(status_code=404, detail=f'Client {client_id} not found')

# Example usage
if __name__ == '__main__':
    limiter = SlidingWindowRateLimiter()
    print(limiter.allow_request('client1', 2, 10))  # True
    print(limiter.allow_request('client1', 2, 10))  # True
    print(limiter.allow_request('client1', 2, 10))  # False
    limiter.remove_client('client1')
    print(limiter.allow_request('client1', 2, 10))  # True
",
  "explanation": "This implementation of SlidingWindowRateLimiter uses a dictionary to store lists of timestamps for each client's requests. The allow_request method checks if the client's request count within the specified time window exceeds the limit. If not, it adds the current timestamp to the list. The remove_client method removes the client's entry from the dictionary if it exists, otherwise it raises an HTTPException."
}
